+function parseCsv(text) {
+  const rows = [];
+  let row = [];
+  let field = "";
+  let quoted = false;
+  for (let i = 0; i < text.length; i++) {
+    const char = text[i];
+    if (quoted && char === '"' && text[i + 1] === '"') {
+      field += '"';
+      i++;
+    } else if (char === '"') {
+      quoted = !quoted;
+    } else if (!quoted && (char === "," || char === "\n" || char === "\r")) {
+      row.push(field);
+      field = "";
+      if (char !== ",") {
+        rows.push(row);
+        row = [];
+        if (char === "\r" && text[i + 1] === "\n") i++;
+      }
+    } else {
+      field += char;
+    }
+  }
+  if (field !== "" || row.length) rows.push([...row, field]);
+  return rows;
+}
